CREATE TABLE scp_turmas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(100) NOT NULL UNIQUE, turno ENUM('manha','tarde','noite','integral') NOT NULL DEFAULT 'manha', ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_usuarios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, perfil ENUM('admin','portaria') NOT NULL, ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_alunos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, cpf CHAR(11) NULL UNIQUE, data_nascimento DATE NULL, turma_id INT UNSIGNED NULL, foto VARCHAR(255) NULL, qr_token CHAR(64) NOT NULL UNIQUE, ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(turma_id) REFERENCES scp_turmas(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_responsaveis (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, cpf CHAR(11) NOT NULL UNIQUE, email VARCHAR(190) NULL, telefone VARCHAR(30) NULL, foto VARCHAR(255) NULL, senha_hash VARCHAR(255) NOT NULL, ativo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_aluno_responsavel (aluno_id INT UNSIGNED NOT NULL, responsavel_id INT UNSIGNED NOT NULL, parentesco VARCHAR(50) NOT NULL, autoriza_consulta TINYINT(1) NOT NULL DEFAULT 1, autoriza_retirada TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(aluno_id,responsavel_id), FOREIGN KEY(aluno_id) REFERENCES scp_alunos(id) ON DELETE CASCADE, FOREIGN KEY(responsavel_id) REFERENCES scp_responsaveis(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_registros_acesso (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, aluno_id INT UNSIGNED NOT NULL, tipo ENUM('entrada','saida') NOT NULL, registrado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, usuario_id INT UNSIGNED NOT NULL, origem VARCHAR(100) NULL, observacao VARCHAR(500) NULL, correcao_manual TINYINT(1) NOT NULL DEFAULT 0, ip VARCHAR(45) NULL, FOREIGN KEY(aluno_id) REFERENCES scp_alunos(id), FOREIGN KEY(usuario_id) REFERENCES scp_usuarios(id), INDEX(aluno_id,registrado_em)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_crachas_emitidos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, aluno_id INT UNSIGNED NOT NULL, emitido_por INT UNSIGNED NOT NULL, emitido_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, token_no_momento CHAR(64) NOT NULL, ativo TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(aluno_id) REFERENCES scp_alunos(id), FOREIGN KEY(emitido_por) REFERENCES scp_usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_logs_auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, usuario_id INT UNSIGNED NULL, responsavel_id INT UNSIGNED NULL, acao VARCHAR(100) NOT NULL, entidade VARCHAR(80) NULL, entidade_id BIGINT NULL, detalhes JSON NULL, ip VARCHAR(45) NULL, criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(criado_em)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_login_tentativas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, chave CHAR(64) NOT NULL UNIQUE, ip VARCHAR(45) NOT NULL, login_hash CHAR(64) NULL, tentativas SMALLINT UNSIGNED NOT NULL DEFAULT 0, bloqueado_ate DATETIME NULL, ultima_tentativa DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(bloqueado_ate), INDEX(ip, ultima_tentativa)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_convites_cadastro (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, telefone VARCHAR(30) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, status ENUM('aguardando','preenchido','aprovado','cancelado','expirado') NOT NULL DEFAULT 'aguardando', criado_por INT UNSIGNED NOT NULL, expira_em DATETIME NOT NULL, responsavel_nome VARCHAR(150) NULL, responsavel_cpf CHAR(11) NULL, responsavel_email VARCHAR(190) NULL, responsavel_foto VARCHAR(255) NULL, aluno_nome VARCHAR(150) NULL, aluno_data_nascimento DATE NULL, aluno_foto VARCHAR(255) NULL, senha_hash VARCHAR(255) NULL, preenchido_em DATETIME NULL, aprovado_em DATETIME NULL, aprovado_por INT UNSIGNED NULL, responsavel_id INT UNSIGNED NULL, aluno_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(criado_por) REFERENCES scp_usuarios(id), FOREIGN KEY(aprovado_por) REFERENCES scp_usuarios(id), FOREIGN KEY(responsavel_id) REFERENCES scp_responsaveis(id), FOREIGN KEY(aluno_id) REFERENCES scp_alunos(id), INDEX(status,created_at), INDEX(telefone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE scp_alertas_cracha (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, aluno_id INT UNSIGNED NOT NULL, qr_token CHAR(64) NOT NULL, nome_informante VARCHAR(150) NULL, telefone_informante VARCHAR(30) NULL, mensagem VARCHAR(500) NULL, latitude VARCHAR(50) NULL, longitude VARCHAR(50) NULL, ip VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, status ENUM('novo','visualizado','resolvido') NOT NULL DEFAULT 'novo', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, visualizado_em DATETIME NULL, resolvido_em DATETIME NULL, FOREIGN KEY(aluno_id) REFERENCES scp_alunos(id) ON DELETE CASCADE, INDEX(status,created_at), INDEX(aluno_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
